interface Courier {
  readonly code: number;
  readonly title: string | null;
  readonly depot?: { readonly name: string };
}

const couriers: readonly Courier[] = [
  { code: 7, title: 'Express', depot: { name: 'North' } },
  { code: 9, title: null },
];

describe('dataElements.choices', () => {
  it('reads each row key and text along its paths', () => {
    expect(dataElements.choices(couriers, ['code'], ['title'])).toEqual([
      { value: 7, label: 'Express' },
      { value: 9, label: '' },
    ]);
  });

  it('follows a nested member chain and treats a missing member as an empty text', () => {
    expect(dataElements.choices(couriers, ['code'], ['depot', 'name'])).toEqual([
      { value: 7, label: 'North' },
      { value: 9, label: '' },
    ]);
  });

  it('offers nothing for no rows', () => {
    expect(dataElements.choices([], ['code'], ['title'])).toEqual([]);
  });

  it('reads the heading of each row along the group path, none for an empty or missing one', () => {
    const topics = [
      { code: 'a', title: 'A', category: 'Fruit' },
      { code: 'b', title: 'B', category: '' },
      { code: 'c', title: 'C' },
    ];
    expect(dataElements.choices(topics, ['code'], ['title'], ['category'])).toEqual([
      { value: 'a', label: 'A', group: 'Fruit' },
      { value: 'b', label: 'B', group: null },
      { value: 'c', label: 'C', group: null },
    ]);
  });

  it('offers a list of keys as choices that are their own key and text (an empty path)', () => {
    expect(dataElements.choices([2024, 2025], [], [])).toEqual([
      { value: 2024, label: '2024' },
      { value: 2025, label: '2025' },
    ]);
  });
});

describe('dataElements.choiceLabel', () => {
  const choices = dataElements.choices(couriers, ['code'], ['title']);

  it('is the text of the choice holding the key', () => {
    expect(dataElements.choiceLabel(choices, 7)).toBe('Express');
  });

  it('is the key itself, as text, when no choice holds it', () => {
    expect(dataElements.choiceLabel(choices, 42)).toBe('42');
  });

  it('is empty for a key that is not set', () => {
    expect(dataElements.choiceLabel(choices, null)).toBe('');
    expect(dataElements.choiceLabel(choices, undefined)).toBe('');
  });
});
